let data=[];const fileInput=document.getElementById('file');const tbody=document.getElementById('rows');async function load(){data=await fetch('../src-data/products.json').then(r=>r.json());draw()}function draw(){tbody.innerHTML=data.map((p,i)=>`<tr><td>${i+1}</td><td><input value="${p.name}" onchange="data[${i}].name=this.value"></td><td><input value="${p.category}" onchange="data[${i}].category=this.value"></td><td><input value="${p.size}" onchange="data[${i}].size=this.value"></td><td><input value="${p.price}" onchange="data[${i}].price=this.value"></td><td><button onclick="data.splice(${i},1);draw()">Delete</button></td></tr>`).join('')}function download(){const b=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='products.json';a.click();URL.revokeObjectURL(a.href)}function csv(){let s='name,category,size,price,brand,type\n'+data.map(p=>[p.name,p.category,p.size,p.price,p.brand,p.type].map(x=>'"'+String(x||'').replaceAll('"','""')+'"').join(',')).join('\n');const b=new Blob([s],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='products.csv';a.click()}fileInput.onchange=async()=>{const t=await fileInput.files[0].text();data=JSON.parse(t);draw()};load();